--
-- Name: get_column_data(); Type: FUNCTION; Schema: public; Owner: lagoaviva
--

CREATE FUNCTION public.get_column_data() RETURNS TABLE(column_value text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    sql_query text;
BEGIN
    SELECT 'SELECT ' || quote_ident(column_name) || ' FROM tbdadoanalisepreenchimento'
    INTO sql_query
    FROM information_schema.columns
    WHERE table_schema = 'public'
    AND table_name = 'tbdadoanalisepreenchimento'
    AND ordinal_position = 4;
    
    RAISE NOTICE 'Executing query: %', sql_query;
    
    RETURN QUERY EXECUTE sql_query;
EXCEPTION
    WHEN OTHERS THEN
        RAISE NOTICE 'Error executing query: %', SQLERRM;
        RETURN;
END;
$$;


ALTER FUNCTION public.get_column_data() OWNER TO lagoaviva;

--
-- Name: separar_operador(text); Type: FUNCTION; Schema: public; Owner: lagoaviva
--

CREATE FUNCTION public.separar_operador(input_valor text) RETURNS TABLE(valor text, operador text)
    LANGUAGE plpgsql
    AS $$
DECLARE
    operadores TEXT := '';
    valor_resultado TEXT := '';
BEGIN
    -- Loop através de cada caractere na string
    FOR i IN 1..LENGTH(input_valor) LOOP
        IF SUBSTRING(input_valor, i, 1) ~ '[<>=]' THEN
            operadores := operadores || SUBSTRING(input_valor, i, 1);
        ELSE
            valor_resultado := valor_resultado || SUBSTRING(input_valor, i, 1);
        END IF;
    END LOOP;
    
    -- Verificar se operadores foram encontrados
    IF operadores = '' THEN
        valor_resultado := input_valor;
    END IF;
    
    RETURN QUERY SELECT TRIM(valor_resultado), operadores;
END;
$$;


ALTER FUNCTION public.separar_operador(input_valor text) OWNER TO lagoaviva;

