--
-- Name: view_intermediaria; Type: VIEW; Schema: public; Owner: lagoaviva
--

CREATE VIEW public.view_intermediaria AS
 SELECT tab_campanha.nome AS campanha,
    tab_coleta.data,
    tab_setor.nome AS setor,
    tab_ponto.nome AS ponto,
    tab_ponto.lat,
    tab_ponto.lon,
    tab_prodxparam.unidade,
    tab_param.nome AS parametro,
    tab_produto.nome AS produto,
    tab_serie_classificacao.nome AS serie,
    tab_frasco.nome AS frasco,
    tab_medida.input_valor AS valor,
    tab_ponto.observacao,
    concat(tab_param.nome, '_', tab_produto.nome, '_', tab_serie_classificacao.nome) AS param_prod_serie
   FROM (((((((((((public.tab_campanha
     JOIN public.tab_coleta ON ((tab_campanha.id = tab_coleta.id_campanha)))
     JOIN public.tab_amostra ON ((tab_coleta.id = tab_amostra.id_coleta)))
     JOIN public.tab_ponto ON ((tab_amostra.id_ponto = tab_ponto.id)))
     JOIN public.tab_setor ON ((tab_ponto.id_setor = tab_setor.id)))
     JOIN public.tab_envio ON ((tab_amostra.id = tab_envio.id_amostra)))
     JOIN public.tab_medida ON ((tab_envio.id = tab_medida.id_envio)))
     JOIN public.tab_prodxparam ON ((tab_medida.id_pp = tab_prodxparam.id)))
     JOIN public.tab_param ON ((tab_prodxparam.id_param = tab_param.id)))
     JOIN public.tab_produto ON ((tab_prodxparam.id_produto = tab_produto.id)))
     JOIN public.tab_serie_classificacao ON ((tab_prodxparam.id_serie = tab_serie_classificacao.id)))
     JOIN public.tab_frasco ON ((tab_prodxparam.id_frasco = tab_frasco.id)));


ALTER VIEW public.view_intermediaria OWNER TO lagoaviva;

--
-- Name: view_com_nova_coluna; Type: VIEW; Schema: public; Owner: lagoaviva
--

CREATE VIEW public.view_com_nova_coluna AS
 SELECT campanha,
