    data,
    ponto,
    lat,
    lon,
    unidade,
    parametro,
    produto,
    serie,
    frasco,
    valor,
    observacao,
    param_prod_serie
   FROM public.view_intermediaria;


ALTER VIEW public.view_com_nova_coluna OWNER TO lagoaviva;

--
-- Name: tab_medida_pivotada; Type: VIEW; Schema: public; Owner: lagoaviva
--

CREATE VIEW public.tab_medida_pivotada AS
 SELECT campanha,
    setor,
    ponto,
    max(
        CASE
            WHEN (param_prod_serie = 'Cádmio_Sedimento_Série de Metais'::text) THEN valor
            ELSE NULL::text
        END) AS "Cádmio_Sedimento_Série de Metais",
    max(
        CASE
            WHEN (param_prod_serie = 'Carbonato_Sedimento_Carbonatatos'::text) THEN valor
            ELSE NULL::text
        END) AS "Carbonato_Sedimento_Carbonatatos",
    max(
        CASE
            WHEN (param_prod_serie = 'Nitrogênio Total_Sedimento_Matéria Orgânica'::text) THEN valor
            ELSE NULL::text
        END) AS "Nitrogênio Total_Sedimento_Matéria Orgânica",
    max(
        CASE
            WHEN (param_prod_serie = 'Areia muito Fina_Sedimento_Granulometria'::text) THEN valor
            ELSE NULL::text
        END) AS "Areia muito Fina_Sedimento_Granulometria",
    max(
        CASE
            WHEN (param_prod_serie = 'Brometo_Água_Íons'::text) THEN valor
            ELSE NULL::text
        END) AS "Brometo_Água_Íons",
    max(
        CASE
            WHEN (param_prod_serie = 'Areia Média_Sedimento_Granulometria'::text) THEN valor
            ELSE NULL::text
        END) AS "Areia Média_Sedimento_Granulometria",
    max(
        CASE
            WHEN (param_prod_serie = 'Sódio_Água_Íons'::text) THEN valor
            ELSE NULL::text
        END) AS "Sódio_Água_Íons",
    max(
        CASE
            WHEN (param_prod_serie = 'Nitrato_Água_Íons'::text) THEN valor
            ELSE NULL::text
        END) AS "Nitrato_Água_Íons",
    max(
        CASE
            WHEN (param_prod_serie = 'Potencial Redox_Sedimento_Matéria Orgânica'::text) THEN valor
            ELSE NULL::text
        END) AS "Potencial Redox_Sedimento_Matéria Orgânica",
    max(
        CASE
            WHEN (param_prod_serie = 'Chumbo_Água_Série de Metais'::text) THEN valor
            ELSE NULL::text
        END) AS "Chumbo_Água_Série de Metais",
    max(
